    void TakeQuickScreenshotNoHud();
};

void CTCPhotojournalCapture::TakeQuickScreenshotNoHud()
{
    if (FrameCounter > 18) {
        WasPlayerGuiOpen = g_pPlayerGui->IsOpen();
        FrameCounter = 0;
        g_pPlayerGui->Close(false);
