void CTCPhotojournalCapture::GlobalUpdate(long frame)
{
    if (FrameCounter < 20) {
        if (++FrameCounter == 18) {
            TakeQuickScreenshot();
            if (WasPlayerGuiOpen)
                g_pPlayerGui->Open();
        }
    }
    if (TakeScreenshotAfterFrames > -1)
        --TakeScreenshotAfterFrames;
    if (TakeScreenshotAfterFrames == 0)
        TakeQuickScreenshot();
}

